using System; using UnityEngine; namespace MyLumo { [Serializable] public class NeedValue { [Range(0,100)] public float value=80; public float drainPerMinute=1; public void Tick(float m)=>value=Mathf.Clamp(value-drainPerMinute*m,0,100); public void Add(float a)=>value=Mathf.Clamp(value+a,0,100); } public class LumoNeeds:MonoBehaviour { public NeedValue hunger=new NeedValue{value=75,drainPerMinute=2},energy=new NeedValue{value=85,drainPerMinute=1.2f},happiness=new NeedValue{value=80,drainPerMinute=.5f},hygiene=new NeedValue{value=90,drainPerMinute=.35f},social=new NeedValue{value=75,drainPerMinute=.45f}; void Update(){float m=Time.deltaTime/60f;hunger.Tick(m);energy.Tick(m);happiness.Tick(m);hygiene.Tick(m);social.Tick(m);} public void AteMeal(){hunger.Add(40);happiness.Add(5);} public void Slept(){energy.Add(65);happiness.Add(6);} public void Danced(){happiness.Add(22);energy.Add(-10);} public void Socialized(){social.Add(35);happiness.Add(12);} } }
